// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1, 10 ether);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        vm.prank(actor);
        bool ok1;
        try c.withdrawAll() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1, "first withdrawAll must succeed");

        vm.prank(actor);
        bool ok2;
        try c.withdrawAll() { ok2 = true; } catch { ok2 = false; }

        assertTrue(ok2, "a repeated withdrawAll must succeed");
    }
}
